```python
import re
import yaml
from pathlib import Path

class SkillLoader:
    &#34;&#34;&#34;从 SKILL.md 文件加载领域知识&#34;&#34;&#34;

    def __init__(self, skills_dir: Path):
        self.skills = {}
        self.load_skills(skills_dir)

    def parse_skill_md(self, path: Path) -&gt; dict:
        &#34;&#34;&#34;解析 YAML 前置元数据 + Markdown 正文&#34;&#34;&#34;
        content = path.read_text()
        match = re.match(r&#39;^---\s*\n(.*?)\n---\s*\n(.*)$&#39;, content, re.DOTALL)
        if not match:
            raise ValueError(f&#34;Invalid SKILL.md format: {path}&#34;)

        metadata = yaml.safe_load(match.group(1))
        return {
            &#34;name&#34;: metadata[&#34;name&#34;],
            &#34;description&#34;: metadata[&#34;description&#34;],
            &#34;body&#34;: match.group(2),
            &#34;path&#34;: path,
            &#34;dir&#34;: path.parent
        }

    def load_skills(self, skills_dir: Path):
        &#34;&#34;&#34;加载所有 SKILL.md 文件&#34;&#34;&#34;
        for skill_md in skills_dir.glob(&#34;*/SKILL.md&#34;):
            skill = self.parse_skill_md(skill_md)
            self.skills[skill[&#34;name&#34;]] = skill

    def get_skill_content(self, name: str) -&gt; str:
        &#34;&#34;&#34;获取技能完整内容，用于注入上下文&#34;&#34;&#34;
        if name not in self.skills:
            return f&#34;Skill &#39;{name}&#39; not found&#34;

        skill = self.skills[name]
        return f&#34;&#34;&#34;&lt;skill-loaded name=&#34;{name}&#34;&gt;

{skill[&#39;body&#39;]}

&lt;/skill-loaded&gt;

请按照上述技能指导完成任务。&#34;&#34;&#34;

    def list_skills(self) -&gt; str:
        &#34;&#34;&#34;生成系统提示词可用的技能索引&#34;&#34;&#34;
        if not self.skills:
            return &#34;(no skills loaded)&#34;
        return &#34;\n&#34;.join(
            f&#34;- {name}: {info[&#39;description&#39;]}&#34;
            for name, info in self.skills.items()
        )渐进式披露策略Skills 采用渐进式披露优化上下文使用：层级内容Tokens 估算加载时机元数据name + description~100始终加载主体完整 SKILL.md~2000触发时资源scripts/, references/无限制按需八、架构总览：全局视角九、设计哲学：大道至简回顾整个架构，我们能提炼出几条核心设计原则：1. 极简核心Agent = 循环 + 工具集合没有状态机，没有复杂的规划模块，没有重框架。核心逻辑可以用一句话概括：给模型工具，让它工作。2. 模型即决策者模型负责：判断何时使用工具选择使用哪些工具决定工具调用的顺序判断任务何时完成代码的角色被压缩到最小：提供工具定义、执行工具调用、管理循环。3. 透明性优先每个工具调用可见，每个结果可追溯。这种透明性带来：易于调试便于理解模型行为支持人工干预4. 渐进式复杂度从 v0 到 v4，架构逐层演进：v0：1 个工具，递归自调用实现子代理v1：4 个核心工具，完整 Agent 循环v2：Todo 追踪，显式规划v3：子代理，上下文隔离v4：Skills，知识外化每一步都建立在前一步之上，没有一步是”必须的”。十、总结Claude Code、Cursor Agent、OpenCode 这些看似复杂的系统，都共享同一个核心模式：while not done:
    response = model(conversation, tools)
    results = execute(response.tool_calls)
    conversation.append(results)差异仅在于：工具丰富度：从单一 bash 到几十个专业工具。交互体验：进度条、权限确认、错误恢复。安全边界：沙盒、权限控制、危险操作拦截。知识储备：从通用模型到加载领域 Skills。但本质从未改变：模型是决策者，代码是执行者，循环是骨架。模型即代理（Model is the Agent）。参考learn-claude-codeKode CLIAgent Skills Spec Anthropic 官方 Skills 规范learn-claude-code
